'use strict';
(()=>{
 const tabs=[...document.querySelectorAll('[data-experience-step]')],panels=[...document.querySelectorAll('[data-experience-panel]')];
 const next=document.querySelector('[data-experience-next]'),back=document.querySelector('[data-experience-back]'),progress=document.querySelector('.experience-progress');
 let current=0;
 function showStep(index,focus=false){current=Math.max(0,Math.min(index,panels.length-1));panels.forEach((p,i)=>{p.hidden=i!==current;p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby',tabs[i].id);});tabs.forEach((t,i)=>{t.setAttribute('aria-selected',String(i===current));t.tabIndex=i===current?0:-1;});if(back)back.disabled=current===0;if(next)next.textContent=current===panels.length-1?'Start again ↺':'Next step →';if(progress)progress.textContent=`Step ${current+1} of ${panels.length}`;if(focus)tabs[current].focus();}
 if(tabs.length){document.querySelector('.experience-tabs').hidden=false;document.querySelector('.experience-controls').hidden=false;tabs.forEach((t,i)=>{t.addEventListener('click',()=>showStep(i));t.addEventListener('keydown',event=>{let n;if(event.key==='ArrowRight')n=(i+1)%tabs.length;if(event.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(event.key==='Home')n=0;if(event.key==='End')n=tabs.length-1;if(n!==undefined){event.preventDefault();showStep(n,true);}});});back.addEventListener('click',()=>showStep(current-1));next.addEventListener('click',()=>showStep(current===panels.length-1?0:current+1));showStep(0);}
 const feedback=document.querySelector('.feedback-actions');if(feedback){feedback.hidden=false;document.querySelector('.demo-defaults').hidden=true;feedback.querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>{feedback.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('.demo-response').textContent=button.dataset.demoResponse==='support'?'A useful review question: was the activity, setting or level of support appropriate? The care team can discuss a smaller step or additional support before agreeing the next plan.':'A useful review question: is the ability becoming reliable in everyday life? The care team can review the response and discuss an appropriate next challenge.';}));}
 const select=document.getElementById('report-choice'),reports=[...document.querySelectorAll('[data-report-panel]')];
 const showReport=id=>{if(!reports.some(r=>r.id===id))return;reports.forEach(r=>r.hidden=r.id!==id);select.value=id;};
 if(select){document.querySelector('.report-picker').hidden=false;select.addEventListener('change',()=>showReport(select.value));showReport(select.value);}
 function reveal(){const id=location.hash.slice(1),node=document.getElementById(id);if(!node)return;const panel=node.closest('[data-experience-panel]');if(panel)showStep(panels.indexOf(panel));const report=node.closest('[data-report-panel]');if(report)showReport(report.id);}
 addEventListener('hashchange',reveal);reveal();
 let printState=[];addEventListener('beforeprint',()=>{printState=[...panels,...reports].map(p=>[p,p.hidden]);printState.forEach(([p])=>p.hidden=false);});addEventListener('afterprint',()=>printState.forEach(([p,hidden])=>p.hidden=hidden));
})();
